import { Transition } from 'framer-motion';

import { NumericDesignToken, DesignToken } from '../../types/token.js';

/**
 * Transforms a easing animation token string to number array so it can be used in framer.
 */
export function convertEasingTokenToFramerMotion(
  easingToken: string,
): number[] {
  const easingValues = easingToken.match(/\((.*?)\)/);

  return easingValues && easingValues.length > 1
    ? easingValues[1].split(',').map((item) => parseFloat(item.trim()))
    : [];
}

/**
 * Creates an easing transition for usage with framer-motion.
 */
export function createFramerMotionTransition(
  durationToken: NumericDesignToken,
  easingToken: DesignToken,
): Transition {
  return {
    duration: durationToken.defaultValueWithoutUnit / 1000,
    ease: convertEasingTokenToFramerMotion(easingToken.defaultValue),
  };
}
